  "summary": "The code contains critical security vulnerabilities including Zip Slip and blocking I/O operations that threaten system stability. I have refactored the code to use non-blocking I/O, implemented strict path sanitization for archives, and introduced environment-based configuration with proper error handling.",
  "fixed_code": "import os\nimport tarfile\nimport uuid\nimport aiofiles\nimport asyncio\nfrom typing import List\nfrom fastapi import FastAPI, File, HTTPException, UploadFile\n\napp = FastAPI()\nUPLOAD_DIR = os.getenv('UPLOAD_DIR', '/var/app/uploads')\nMAX_BYTES = 5 * 1024 * 1024\n\n@app.post(\"/avatars\")\nasync def upload_avatar(file: UploadFile = File(...)):\n    \"\"\"Uploads a PNG avatar, validates size and format, and saves it to the UPLOAD_DIR.\"\"\"\n    data = await file.read(MAX_BYTES + 1)\n    if len(data) > MAX_BYTES:\n        raise HTTPException(status_code=413, detail=\"file too large\")\n    if not data.startswith(b\"\\x89PNG\\r\\n\\x1a\\n\"):\n        raise HTTPException(status_code=415, detail=\"PNG only\")\n    \n    stored = f\"{uuid.uuid4().hex}.png\"\n    path = os.path.join(UPLOAD_DIR, stored)\n    \n    try:\n        async with aiofiles.open(path, \"wb\") as fh:\n            await fh.write(data)\n    except Exception as e:\n        raise HTTPException(status_code=500, detail=\"Storage error\")\n    return {\"stored_as\": stored}\n\nasync def import_backup(archive_path: str, dest: str) -> List[str]:\n    \"\"\"Extracts a tar archive safely to the destination directory.\"\"\"\n    os.makedirs(dest, exist_ok=True)\n    \n    def _extract():\n        with tarfile.open(archive_path) as tar:\n            for member in tar.getmembers():\n                if '..' in member.name or member.name.startswith('/'):\n                    raise ValueError(\"Malicious archive path\")\n            tar.extractall(dest, filter=\"data\")\n        return sorted(os.listdir(dest))\n\n    loop = asyncio.get_event_loop()\n    return await loop.run_in_executor(None, _extract)"
}
